      'Here\'s a simple text-based quiz program in Zig that asks about country capitals. The program will keep track of the score and provide feedback after each question:\n```zig\nconst std = @import("std");\n\nconst countries = [_]struct {\n    country: []const u8,\n    capital: []const u8,\n    options: [3][]const u8,\n}{\n    .{ "France", "Paris", &[_][]const u8{"Paris", "Marseille", "Lyon"} },\n    .{ "Japan", "Tokyo", &[_][]const u8{"Tokyo", "Osaka", "Kyoto"} },\n    .{ "Canada", "Ottawa", &[_][]const u8{"Ottawa", "Toronto", "Montreal"} },\n    .{ "Germany", "Berlin", &[_][]const u8{"Berlin", "Munich", "Hamburg"} },\n    .{ "Australia", "Canberra", &[_][]const u8{"Canberra", "Sydney", "Melbourne"} },\n};\n\npub fn main() !void {\n    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);\n    defer arena.deinit();\n    const allocator = &arena.allocator;\n\n    var score: u32 = 0;\n\n    for (countries) |country, i| {\n        const answer = try askQuestion(i, &country, allocator);\n        if (std.ascii.eqlIgnoreCase(u8, country.capital, answer)) {\n            score += 1;\n        }\n        printScore(score);\n    }\n}\n\nfn askQuestion(question_num: usize, country: *const struct {\n    country: []const u8,\n    capital: []const u8,\n    options: [3][]const u8,\n}, allocator: *std.mem.Allocator) ![]u8 {\n    std.debug.print("Question {d}/5: Which city is the capital of {s}? ", .{ question_num + 1, country.country });\n    for (country.options) |option, i| {\n        std.debug.print("{d}) {s} ", .{ i + 1, option });\n    }\n    std.debug.print("\\nYour answer: ", .{});\n\n    const answer = try std.io.getStdIn().reader().readUntilDelimiterAlloc(allocator, \'\\n\', 100);\n    try std.debug.print("Correct answer: {s}\\n", .{country.capital});\n    return answer;\n}\n\nfn printScore(score: u32) void {\n    std.debug.print("Score: {}/{}\\n", .{ score, countries.len });\n}\n```\n\nTo run this code, you\'ll need Zig installed. Save the code to a file (e.g., `quiz.zig`), and then compile and run it using the Zig compiler:\n```bash\nzig build run\n```\n\nThis will run the quiz and display the questions, options, and your running score.',
